# Lanternhold v125: player activity log ("View Log" in the Admin tab). Paste into AWS CloudShell (us-east-1).
# Needs John's go. It backs up the current code to ~/lhbak first. Safe to run twice.
# Note: the admin code below also carries the waiting "where players came from" change (PR 9).
set -e
R=us-east-1; API=nyu3u8gc73; TS=$(date +%Y%m%d%H%M)
mkdir -p ~/lhbak ~/lhv125/save ~/lhv125/admin && cd ~/lhv125
for f in lanternhold-save lanternhold-admin; do curl -s "$(aws lambda get-function --function-name $f --query Code.Location --output text)" -o ~/lhbak/$f-$TS.zip; done
echo "backups: $(ls ~/lhbak | grep $TS)"
# 1. let the save Lambda write log rows to the trade table
ROLE=$(aws lambda get-function-configuration --function-name lanternhold-save --query Role --output text | awk -F/ '{print $NF}')
TARN=$(aws dynamodb describe-table --table-name lanternhold-trade --query Table.TableArn --output text)
aws iam put-role-policy --role-name "$ROLE" --policy-name lanternhold-activity-log --policy-document "{\"Version\":\"2012-10-17\",\"Statement\":[{\"Effect\":\"Allow\",\"Action\":\"dynamodb:PutItem\",\"Resource\":\"$TARN\"}]}"
TABLE=$(aws lambda get-function-configuration --function-name lanternhold-save --query Environment.Variables.TABLE --output text)
aws lambda update-function-configuration --function-name lanternhold-save --environment "Variables={TABLE=$TABLE,TRADE=lanternhold-trade}" >/dev/null
aws lambda wait function-updated --function-name lanternhold-save
# 2. new code (built from infra/lambda/save.js and admin.js by esbuild)
echo  | base64 -d > save/index.js
echo  | base64 -d > admin/index.js
(cd save && zip -qj ../save.zip index.js) && (cd admin && zip -qj ../admin.zip index.js)
aws lambda update-function-code --function-name lanternhold-save --zip-file fileb://save.zip >/dev/null
aws lambda update-function-code --function-name lanternhold-admin --zip-file fileb://admin.zip >/dev/null
aws lambda wait function-updated --function-name lanternhold-save && aws lambda wait function-updated --function-name lanternhold-admin
# 3. route GET /admin/log to the admin Lambda, with the same sign-in check as GET /admin/players
if [ -z "$(aws apigatewayv2 get-routes --api-id $API --query "Items[?RouteKey=='GET /admin/log'].RouteId" --output text)" ]; then
  INT=$(aws apigatewayv2 get-routes --api-id $API --query "Items[?RouteKey=='GET /admin/players'].Target" --output text)
  AUTH=$(aws apigatewayv2 get-routes --api-id $API --query "Items[?RouteKey=='GET /admin/players'].AuthorizerId" --output text)
  aws apigatewayv2 create-route --api-id $API --route-key 'GET /admin/log' --authorization-type JWT --authorizer-id "$AUTH" --target "$INT" >/dev/null
fi
# 4. smoke test: both must say 401 (no sign-in)
curl -s -o /dev/null -w "admin/log %{http_code}\n" "https://$API.execute-api.$R.amazonaws.com/admin/log?id=0000000000000000"
curl -s -o /dev/null -w "save %{http_code}\n" -X PUT "https://$API.execute-api.$R.amazonaws.com/save"
echo "done. Undo: aws lambda update-function-code --function-name lanternhold-save --zip-file fileb://$HOME/lhbak/lanternhold-save-$TS.zip (same for admin)"
